<script lang="ts">
 import type {productInsights} from '$lib/server/productInsights';
 import Title from './Title.svelte';import PeriodPicker from './PeriodPicker.svelte';import ContributionList from './ContributionList.svelte';import {formatMoney,monthLabel} from '$lib/utils';
 let {data}:{data:ReturnType<typeof productInsights>}=$props();
 const income=$derived(data.type==='income'),title=$derived(income?'Income':'Spending'),path=$derived(income?'/income':'/spending');
 const total=$derived(income?data.summary.incomeCents:data.summary.spendingCents);
 const maxCategory=$derived(Math.max(1,...data.categoryRows.map(c=>Math.abs(c.cents))));
 const maxHistory=$derived(Math.max(1,...data.history.map(h=>Math.abs(h.cents))));
</script>
<Title {title}/><div class="product-page"><header class="product-heading"><div><h1>{title}</h1><p>{income?'See what you earned, without counting money moved between accounts.':'Understand your spending, with refunds put back in the right place.'}</p></div><a class="product-button" href={`/transactions?date_from=${data.period.from}&date_to=${data.period.dateTo}&status=posted`}>Open activity</a></header><PeriodPicker month={data.period.month} {path}/>
<section class="product-summary" aria-label={`${title} summary`}><div><span class="metric-label">{income?'Income received':'Net spending'}</span><strong class="metric-value">{formatMoney(total)}</strong><span class="metric-context">{monthLabel(data.period.from)} · posted activity</span></div><div><span class="metric-label">{income?'Income categories':'Spending categories'}</span><strong class="metric-value">{data.categoryRows.length}</strong><span class="metric-context">Open a category to explore it</span></div><div><span class="metric-label">Needs review</span><strong class="metric-value">{data.summary.uncategorizedCount}</strong><a class="metric-context product-link" href={`/transactions?empty=category&date_from=${data.period.from}&date_to=${data.period.dateTo}&status=posted`}>Uncategorized transactions</a></div></section>
<div class="product-columns"><section class="product-panel"><header class="product-panel-header"><h2>{income?'Where income came from':'Spending by category'}</h2></header>{#if data.categoryRows.length}<div class="product-panel-body"><ul class="product-bars">{#each data.categoryRows as c}<li><a href={`/categories/${c.id}?${data.period.query}`}><div class="product-bar-caption"><span>{c.name}</span><strong>{formatMoney(income?c.cents:-c.cents)}</strong></div><div class="product-bar-track" aria-hidden="true"><div class="product-bar-fill" style:width={`${Math.abs(c.cents)/maxCategory*100}%`}></div></div></a></li>{/each}</ul></div>{:else}<div class="product-empty"><strong>No categorized {title.toLowerCase()} yet</strong><p>Review your transactions or choose another month.</p></div>{/if}</section>
<section class="product-panel"><header class="product-panel-header"><h2>Six-month view</h2></header><div class="product-panel-body"><ul class="product-bars">{#each data.history as h}<li><a href={`${path}?month=${h.month}`}><div class="product-bar-caption"><span>{monthLabel(`${h.month}-01`)}</span><strong>{h.postedCount?formatMoney(h.cents):'No activity'}</strong></div>{#if h.postedCount}<div class="product-bar-track" aria-hidden="true"><div class="product-bar-fill" style:width={`${Math.abs(h.cents)/maxHistory*100}%`}></div></div>{/if}{#if h.uncategorizedCount}<span class="product-row-caption">Some activity still needs a category</span>{/if}</a></li>{/each}</ul></div><div class="product-details">Based on available recorded activity, not a guarantee of complete history.</div></section></div>
<section class="product-panel"><header class="product-panel-header"><h2>Transactions behind this total</h2></header><ContributionList rows={data.contributions} expense={!income}/></section>
<details class="product-panel product-details"><summary>What is included?</summary><p>{income?'Posted transactions in income categories, less income reversals. Transfers, card payments, refunds and unclassified deposits are not counted as earnings.':'Posted transactions in expense categories, less refunds in those categories. Transfers, card payments and unclassified activity are excluded. A negative total means net refunds in the period.'} Split transactions contribute only their matching portions. Pending transactions are excluded.</p></details></div>
